inline void get_normals(const double* moments, double (&normal)[6]) {
    double tmp1[256] = {0.0};
    double tmp2[256] = {0.0};
    double tmp3[256] = {0.0};
    for (int j = 0; j < 256; ++j) {
        tmp1[j] = lay1_bias[j];
        for (int i = 0; i < 192; ++i)
            tmp1[j] += moments[i] * lay1_weight[j][i];
        if (tmp1[j] < 0.0) tmp1[j] = 0.0;
    }

    for (int j = 0; j < 256; ++j) {
        tmp2[j] = lay2_bias[j];
        for (int i = 0; i < 256; ++i)
            tmp2[j] += tmp1[i] * lay2_weight[j][i];
        if (tmp2[j] < 0.0) tmp2[j] = 0.0;
    }

    for (int j = 0; j < 256; ++j) {
        tmp3[j] = lay3_bias[j];
        for (int i = 0; i < 256; ++i)
            tmp3[j] += tmp2[i] * lay3_weight[j][i];
        if (tmp3[j] < 0.0) tmp3[j] = 0.0;
    }

    for (int j = 0; j < 6; ++j) {
        normal[j] = lay4_bias[j];
        for (int i = 0; i < 256; ++i)
            normal[j] += tmp3[i] * lay4_weight[j][i];
    }
}


